-- What was actually said on each call. 120 notes across the 36 enquiries
-- that someone has spoken to.
--
-- These read like real conversations on purpose. "Note 1, note 2" on a
-- lead detail page tells a reviewer the screen is fake, and once they
-- believe that about one part they stop trusting the numbers too.
--
-- The author of a note is always the sales person who owns the row.
-- I leave the id out so MySQL numbers these in insert order.

INSERT INTO notes (enquiry_id, user_id, body, created_at) VALUES

